import{a as e,c as t,i as n,l as r,s as i}from"./app-C2n4grsf.js";import{t as a}from"./plugin-vue_export-helper-BDNMzG2s.js";var o=JSON.parse(`{"path":"/Linux/basics/linux-03-tcpdump.html","title":"tcpdump 抓包——从抓到第一行 ping，滚到定位真实的连接拒绝","lang":"zh-CN","frontmatter":{"title":"tcpdump 抓包——从抓到第一行 ping，滚到定位真实的连接拒绝","sidebarGroup":"Linux 基础","shortTitle":"03 tcpdump 抓包入门","order":3,"date":"2026-08-17T00:00:00.000Z","category":"Linux","tag":["Linux","网络","tcpdump","抓包","Docker前置"],"description":"从在 lo 上抓到第一行 ping 开始，每次只加一个因素：三件套、结尾统计与 any、-nn、BPF 过滤器、TCP Flags、回读 ss 账本、-A 明文、docker0 抓容器、-w/-r 存取——同一条流量一路滚大，全部命令与输出在 WSL2 实测。","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"tcpdump 抓包——从抓到第一行 ping，滚到定位真实的连接拒绝\\",\\"image\\":[\\"\\"],\\"datePublished\\":\\"2026-08-17T00:00:00.000Z\\",\\"dateModified\\":\\"2026-08-19T03:04:07.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"Corey\\",\\"url\\":\\"https://www.code-corey.com\\"}]}"],["meta",{"property":"og:url","content":"https://www.code-corey.com/Linux/basics/linux-03-tcpdump.html"}],["meta",{"property":"og:site_name","content":"Corey 知识库"}],["meta",{"property":"og:title","content":"tcpdump 抓包——从抓到第一行 ping，滚到定位真实的连接拒绝"}],["meta",{"property":"og:description","content":"从在 lo 上抓到第一行 ping 开始，每次只加一个因素：三件套、结尾统计与 any、-nn、BPF 过滤器、TCP Flags、回读 ss 账本、-A 明文、docker0 抓容器、-w/-r 存取——同一条流量一路滚大，全部命令与输出在 WSL2 实测。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-08-19T03:04:07.000Z"}],["meta",{"property":"article:tag","content":"Docker前置"}],["meta",{"property":"article:tag","content":"抓包"}],["meta",{"property":"article:tag","content":"tcpdump"}],["meta",{"property":"article:tag","content":"网络"}],["meta",{"property":"article:tag","content":"Linux"}],["meta",{"property":"article:published_time","content":"2026-08-17T00:00:00.000Z"}],["meta",{"property":"article:modified_time","content":"2026-08-19T03:04:07.000Z"}]]},"git":{"createdTime":1786949206000,"updatedTime":1787108647000,"contributors":[{"name":"chengongyi","username":"chengongyi","email":"2363613998@qq.com","commits":3,"url":"https://github.com/chengongyi"},{"name":"Claude","username":"Claude","email":"noreply@anthropic.com","commits":1,"url":"https://github.com/Claude"}]},"readingTime":{"minutes":25.24,"words":7572},"filePathRelative":"Linux/basics/linux-03-tcpdump.md","excerpt":"<blockquote>\\n<p><strong>Linux 板块 · 第 3 篇</strong><br>\\n上一篇：<a href=\\"/Linux/basics/linux-02-ip-subnet-gateway\\">《IP、网段与网关》</a><br>\\n下一篇：<a href=\\"/Linux/basics/linux-04-nat\\">《NAT 现场实录》</a>（本文练好的抓包功夫，正好去拍 NAT 换头的现行）</p>\\n</blockquote>\\n<hr>\\n<h2>开头：端口明明 LISTEN，就是连不上</h2>\\n<p>排障时最憋屈的一类问题长这样（本机实测）——服务说自己在监听：</p>"}`),s={name:`linux-03-tcpdump.md`};function c(a,o,s,c,l,u){let d=r(`Mermaid`);return t(),n(`div`,null,[o[0]||=e(`<blockquote><p><strong>Linux 板块 · 第 3 篇</strong><br> 上一篇：<a href="/Linux/basics/linux-02-ip-subnet-gateway">《IP、网段与网关》</a><br> 下一篇：<a href="/Linux/basics/linux-04-nat">《NAT 现场实录》</a>（本文练好的抓包功夫，正好去拍 NAT 换头的现行）</p></blockquote><hr><h2 id="开头-端口明明-listen-就是连不上" tabindex="-1"><a class="header-anchor" href="#开头-端口明明-listen-就是连不上"><span>开头：端口明明 LISTEN，就是连不上</span></a></h2><p>排障时最憋屈的一类问题长这样（本机实测）——服务说自己在监听：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">ss</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -tln</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> | </span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">grep</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 18097</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>LISTEN 0      5          127.0.0.1:18097      0.0.0.0:*</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>可客户端一连就吃闭门羹：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">curl</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> http://172.22.212.111:18097/</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>curl: (7) Failed to connect to 172.22.212.111 port 18097: Connection refused</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><code>ss</code> 说端口在听，<code>iptables</code> 说规则没拦——可包到底有没有到？到了之后发生了什么？谁也没说。换 tcpdump 上场，现场一秒破案：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>$ tcpdump -ni lo tcp port 18097 -c 2</span></span>
<span class="line"><span>14:18:13.596940 IP 172.22.212.111.40386 &gt; 172.22.212.111.18097: Flags [S], ...</span></span>
<span class="line"><span>14:18:13.596950 IP 172.22.212.111.18097 &gt; 172.22.212.111.40386: Flags [R.], ...</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>连接请求（<code>[S]</code>）落地仅 <strong>10 微秒</strong>，内核直接回了拒绝（<code>[R.]</code>）——因为这个服务只绑在 <code>127.0.0.1</code> 上（第 2 篇讲过：<code>scope host</code> 的地址只在本机内部转），从 <code>172.22.212.111</code> 这个门牌进来的请求「没人认领」。换 <code>curl http://127.0.0.1:18097/</code> 立刻就通。这两行里的 <code>[S]</code>、<code>[R.]</code> 是什么意思，雪球 5 会给你整张字母表。</p><p>根因一句话：<strong><code>ss</code>、<code>iptables</code> 这类工具读的是内核里登记的「配置」，是账本；而「包来没来、来了被谁怎么处理」是发生过的事件——账本不记事件</strong>，所以配置全对却连不上时，只能去调监控。tcpdump 就是这台对着网卡的监控录像机：</p><table><thead><tr><th>层</th><th>工具</th><th>看到的是</th><th>类比</th></tr></thead><tbody><tr><td>配置层</td><td><code>ip</code>、<code>ss</code>、<code>iptables</code>、<code>docker network inspect</code></td><td>内核里<strong>登记了什么</strong></td><td>账本</td></tr><tr><td>事件层</td><td><strong>tcpdump</strong>、Wireshark</td><td>包<strong>实际发生了什么</strong></td><td>监控录像</td></tr></tbody></table><p>账本可以有借条没还上、规则开着却不生效——录像不会撒谎。「LISTEN 了却 refused」「规则放行了却不通」「容器能 ping 通 IP 却 curl 不动」，这类问题的最终裁判都是抓包。第 4 篇拆 NAT 时还要靠它两侧抓包拍现行——本文先把这件兵器正式交到你手上。</p><p>本篇不先背参数。<strong>同一条流量一路滚大</strong>：先在 lo 上抓自己的 ping 抓到第一行，再把一次 <code>curl</code> 的 12 行逐字段读懂，最后把镜头转向 docker0 上容器的那条 <code>curl</code>，用它定位真实问题：</p><table><thead><tr><th>雪球</th><th>这一球加上去的</th><th>当场能看见的效果</th></tr></thead><tbody><tr><td><strong>1</strong></td><td>三件套 <code>-i</code> / <code>-n</code> / <code>-c</code>（外加 <code>-D</code> 认口）</td><td>lo 上一次 ping，请求/应答 4 行上屏</td></tr><tr><td><strong>2</strong></td><td>结尾统计三行 + <code>any</code> 虚拟口</td><td>「8 收到对 4 抓到」之谜解开，每行多了 <code>In</code>/<code>Out</code> 方向</td></tr><tr><td><strong>3</strong></td><td>把 <code>-n</code> 拧紧到 <code>-nn</code></td><td><code>localhost</code> 不再顶替 <code>127.0.0.1</code>，端口也不被翻译</td></tr><tr><td><strong>4</strong></td><td>BPF 过滤器</td><td>eth0 上 4 行全是与 223.5.5.5 的对话</td></tr><tr><td><strong>5</strong></td><td>TCP Flags 字母表</td><td>一次 <code>curl</code> 从握手到挥手 12 行全读懂；开头那记 <code>[R.]</code> 结案</td></tr><tr><td><strong>6</strong></td><td>一本账对照：读透 <code>ss</code></td><td><code>Local Address</code> 两种写法一对比，门开在哪一眼看清</td></tr><tr><td><strong>7</strong></td><td><code>-A</code> + <code>-s0</code></td><td><code>GET /hello?name=world</code> 请求原文现形</td></tr><tr><td><strong>8</strong></td><td>换口到 docker0（容器流量）</td><td><code>GET /</code> 与 <code>200 OK</code> 全程上屏；同一过滤器在 eth0 零包</td></tr><tr><td><strong>9</strong></td><td><code>-w</code> / <code>-r</code> 存取 pcap</td><td>包变成可回放的文件，回读连特权都不要</td></tr></tbody></table><blockquote><p><strong>贯穿场景</strong>：同一台 WSL2；练手服务一律 <code>python3 -m http.server</code>（开头 18097、雪球 5 用 18099、雪球 7 用 18098），抓包产物统一放 <code>/tmp</code>。<br><strong>环境指纹</strong>：WSL2 Ubuntu-22.04，tcpdump <strong>4.99.1</strong> + libpcap 1.10.1（Ubuntu 22.04 仓库版；上游最新稳定版 4.99.6，2025-12-30 发布），Docker Engine 29.1.3。抓包需要 root（准确说是 <code>CAP_NET_RAW</code> 能力），本环境默认用户即 root；你在普通用户环境里命令前加 <code>sudo</code>。<br><strong>官方入口</strong>：<a href="https://www.tcpdump.org/manpages/tcpdump.1.html" target="_blank" rel="noopener noreferrer">tcpdump(1) 手册</a>、<a href="https://www.tcpdump.org/manpages/pcap-filter.7.html" target="_blank" rel="noopener noreferrer">pcap-filter(7) 过滤器语法</a>、<a href="https://www.tcpdump.org/" target="_blank" rel="noopener noreferrer">tcpdump.org</a>。本文全部写法在 4.99 与上游新版通用。<br><strong>读完你能</strong>：独立完成一次「选接口 → 写过滤器 → 抓包 → 逐字段读懂 → 存文件回放」的完整排障；看到 <code>[S]</code>、<code>[S.]</code>、<code>[R.]</code>、<code>[P.]</code> 能立刻说出发生了什么。</p></blockquote><blockquote><p>想亲手复现开头这个现场：<code>python3 -m http.server 18097 --bind 127.0.0.1 &amp;</code> 起一个只绑回环的服务，再拿 eth0 的地址去 curl 它。</p></blockquote><hr><h2 id="雪球-1-加上-i-n-c-三件套-在-lo-上抓到第一行" tabindex="-1"><a class="header-anchor" href="#雪球-1-加上-i-n-c-三件套-在-lo-上抓到第一行"><span>雪球 1：加上 <code>-i</code>/<code>-n</code>/<code>-c</code> 三件套，在 lo 上抓到第一行</span></a></h2><p>tcpdump 做的事一句话讲完：<strong>把流经某个网络接口的包复制一份</strong>，解析后打印在屏幕上，或原样存进文件。它不转发、不修改、不影响网络——只是「旁听」。</p><p>它凭什么看得见？底下干活的是 <strong>libpcap</strong> 库（Windows 上同类叫 Npcap；Wireshark 的抓包引擎也是它）。在 Linux 上，libpcap 通过内核的 <strong>AF_PACKET</strong> 机制从网卡驱动层取包——这个旁听点很靠底，所以连被防火墙丢弃前后的包、转发中的包都看得见。也正因为它能看「别人的信」，读取网卡的原始包是特权操作（root / <code>CAP_NET_RAW</code>）；读已保存的 pcap 文件则不需要特权（雪球 9 验证）。</p><p>先确认手上的版本：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">tcpdump</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> --version</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>tcpdump version 4.99.1</span></span>
<span class="line"><span>libpcap version 1.10.1 (with TPACKET_V3)</span></span>
<span class="line"><span>OpenSSL 3.0.2 15 Mar 2022</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_1-1-先认口-d-列出能抓谁" tabindex="-1"><a class="header-anchor" href="#_1-1-先认口-d-列出能抓谁"><span>1.1 先认口：<code>-D</code> 列出能抓谁</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">tcpdump</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -D</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>1.eth0 [Up, Running, Connected]</span></span>
<span class="line"><span>2.docker0 [Up, Running, Connected]</span></span>
<span class="line"><span>3.vethd1f1123 [Up, Running, Connected]</span></span>
<span class="line"><span>4.vethbf20c82 [Up, Running, Connected]</span></span>
<span class="line"><span>5.vethfb8f8a7 [Up, Running, Connected]</span></span>
<span class="line"><span>6.any (Pseudo-device that captures on all interfaces) [Up, Running]</span></span>
<span class="line"><span>7.lo [Up, Running, Loopback]</span></span>
<span class="line"><span>8.br-232b31f9d168 [Up, Disconnected]</span></span>
<span class="line"><span>...（省略若干 br- 开头的自定义网桥与系统虚拟设备）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>值得认识的面孔，立刻钉成一张表：</p><table><thead><tr><th>接口</th><th>是谁</th></tr></thead><tbody><tr><td><code>eth0</code></td><td>WSL 对外的物理侧网卡</td></tr><tr><td><code>docker0</code></td><td>Docker 默认网桥，第 2 篇的老朋友</td></tr><tr><td><code>lo</code></td><td>环回，只跑本机内部流量，最干净，适合练手</td></tr><tr><td><code>veth*</code></td><td>容器网线的宿主侧（第 2 篇 <code>eth0@if88</code> 的伏笔）</td></tr><tr><td><code>any</code></td><td>虚拟口，汇总所有接口，雪球 2 用</td></tr></tbody></table><p><strong>抓哪张口，就看见谁的流量</strong>——这句话贯穿全文，雪球 8 会拿它破一桩案子。</p><h3 id="_1-2-第一个抓包-在-lo-上抓-ping" tabindex="-1"><a class="header-anchor" href="#_1-2-第一个抓包-在-lo-上抓-ping"><span>1.2 第一个抓包：在 lo 上抓 ping</span></a></h3><p><code>lo</code> 上只有本机自己的流量，不会被别人的包刷屏。一个终端抓包、另一个终端 <code>ping</code>（合成一条命令的话把抓包放后台）：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">tcpdump</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -ni</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> lo</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> icmp</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -c</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 4</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> &amp;</span></span>
<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">ping</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -c</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 2</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 127.0.0.1</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>命令第一次出现，逐片拆开（后面九成的抓包都是它们的组合）：</p><table><thead><tr><th>片段</th><th>含义</th></tr></thead><tbody><tr><td><code>-i lo</code></td><td>监听 lo 这张口（<strong>i</strong>nterface）</td></tr><tr><td><code>-n</code></td><td>地址显示数字，不做名字解析（雪球 3 专讲为什么）</td></tr><tr><td><code>icmp</code></td><td>过滤器：只要 ICMP 包（雪球 4 专讲）</td></tr><tr><td><code>-c 4</code></td><td>抓满 4 个包就退出（<strong>c</strong>ount），练手时防止刷屏</td></tr><tr><td><code>&amp;</code></td><td>把 tcpdump 放后台，腾出终端敲 ping</td></tr><tr><td><code>ping -c 2</code></td><td>发 2 个探测包就停（第 2 篇用过）</td></tr></tbody></table><p>本机输出：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>tcpdump: verbose output suppressed, use -v[v]... for full protocol decode</span></span>
<span class="line"><span>listening on lo, link-type EN10MB (Ethernet), snapshot length 262144 bytes</span></span>
<span class="line"><span>14:03:01.531082 IP 127.0.0.1 &gt; 127.0.0.1: ICMP echo request, id 1, seq 1, length 64</span></span>
<span class="line"><span>14:03:01.531090 IP 127.0.0.1 &gt; 127.0.0.1: ICMP echo reply, id 1, seq 1, length 64</span></span>
<span class="line"><span>14:03:02.549638 IP 127.0.0.1 &gt; 127.0.0.1: ICMP echo request, id 1, seq 2, length 64</span></span>
<span class="line"><span>14:03:02.549649 IP 127.0.0.1 &gt; 127.0.0.1: ICMP echo reply, id 1, seq 2, length 64</span></span>
<span class="line"><span>4 packets captured</span></span>
<span class="line"><span>8 packets received by filter</span></span>
<span class="line"><span>0 packets dropped by kernel</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>一次就抓到了完整的请求/应答。开头两行 banner 也是信息：<code>verbose output suppressed</code> 表示默认精简模式（<code>-v</code> 才展开全部协议字段）；<code>listening on lo</code> 是正在监听的口；<code>link-type EN10MB</code> 表示按以太网帧解析（EN10MB 是以太网的代号）；<code>snapshot length 262144</code> 是<strong>默认抓取长度</strong>（snaplen，够覆盖常见整包，截断话题雪球 7 展开）。挑第一行数据逐字段拆：</p><table><thead><tr><th>字段</th><th>一句话</th></tr></thead><tbody><tr><td><code>14:03:01.531082</code></td><td>时间戳，精确到微秒——第 4 篇靠它认「同一个包」在两张网卡上的时差</td></tr><tr><td><code>IP</code></td><td>这是个 IPv4 包</td></tr><tr><td><code>127.0.0.1 &gt; 127.0.0.1</code></td><td>源地址 &gt; 目的地址；lo 上自己发给自己，两边都是自己</td></tr><tr><td><code>ICMP echo request</code></td><td>包的类型：ping 的「请问有人吗」</td></tr><tr><td><code>id 1</code></td><td>标识是哪一次 ping（Linux 拿进程号充当）；同一次 ping 里 id 不变，四行全是 <code>id 1</code></td></tr><tr><td><code>seq 1</code></td><td>这次 ping 发出的第几个包，从 1 递增（下一对就是 <code>seq 2</code>）</td></tr><tr><td><code>length 64</code></td><td>ICMP 载荷 64 字节（ping 的默认大小）</td></tr></tbody></table><p>request/reply 成对出现、seq 递增——ping 的流量就这么好认。结尾那三行统计先按下不表，下一球专门拆。</p><hr><h2 id="雪球-2-加上结尾统计三行-顺手用-any-看方向" tabindex="-1"><a class="header-anchor" href="#雪球-2-加上结尾统计三行-顺手用-any-看方向"><span>雪球 2：加上结尾统计三行，顺手用 <code>any</code> 看方向</span></a></h2><p>每场抓包结束时 tcpdump 都会交代三句话，原样抠出来：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>4 packets captured        ← tcpdump 实际收到并处理的包数</span></span>
<span class="line"><span>8 packets received by filter   ← 内核过滤器放行给抓包机制的包数</span></span>
<span class="line"><span>0 packets dropped by kernel    ← 内核缓冲区不够而丢弃的包数</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>坑：为什么是 8 对 4？丢了一半吗？</strong> 手册原话：<code>received by filter</code> 的<strong>语义依赖操作系统</strong>，可能包含 tcpdump 尚未处理的包。在 Linux 的 lo 上，同一个包「发出」和「到达」各经过旁听点一次，内核按 8 次计数，tcpdump 呈现时合并为 4 个——<strong>数字不一致是正常现象，不是丢了包</strong>。验证它很容易：用 <code>any</code> 这个虚拟口抓，输出会带方向标记：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>$ tcpdump -ni any &quot;icmp and host 127.0.0.1&quot; -c 4</span></span>
<span class="line"><span>14:07:47.425172 lo    In  IP 127.0.0.1 &gt; 127.0.0.1: ICMP echo request, id 5, seq 1, length 64</span></span>
<span class="line"><span>14:07:47.425182 lo    In  IP 127.0.0.1 &gt; 127.0.0.1: ICMP echo reply, id 5, seq 1, length 64</span></span>
<span class="line"><span>...</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>any</code> 汇总所有接口的流量，并多打印<strong>接口名 + 方向</strong>：<code>lo In</code> 表示这个包正从 lo 进本机（<code>Out</code> 则是出本机）。排障时「不知道包走哪张口」，先 <code>tcpdump -ni any</code> 定位，再换到具体接口上细抓，是常用套路。</p><p>真正要盯的是第三行：<code>dropped by kernel</code> 不为 0，说明包多得 tcpdump 来不及取，<strong>现场已经失真</strong>——对策是收紧过滤器（雪球 4）、加 <code>-c</code>、或直接落盘（雪球 9）。</p><blockquote><p><strong>雪球 2 补</strong>：抓包结束先看最后一行再看来往内容。<code>dropped by kernel</code> 非 0 的抓包不能当排障证据——先改命令（收窄/限数/落盘）再抓一次。</p></blockquote><hr><h2 id="雪球-3-把-n-拧紧到-nn-别让工具自作主张查名字" tabindex="-1"><a class="header-anchor" href="#雪球-3-把-n-拧紧到-nn-别让工具自作主张查名字"><span>雪球 3：把 <code>-n</code> 拧紧到 <code>-nn</code>，别让工具自作主张查名字</span></a></h2><p>不加 <code>-n</code> 时，tcpdump 会试着把地址反解析成名字。对比同一批包：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>$ tcpdump -i lo icmp -c 2        （无 -n）</span></span>
<span class="line"><span>14:03:04.625701 IP localhost &gt; localhost: ICMP echo request, id 2, seq 1, length 64</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><code>127.0.0.1</code> 变成了 <code>localhost</code>。看着亲切，代价有三：<strong>反解要查 DNS，慢</strong>（地址多时肉眼可见地卡）；<strong>查询本身产生流量</strong>，污染你要观察的现场；<strong>解析可能失败或张冠李戴</strong>。所以排障口诀是：<strong>永远 <code>-n</code></strong>。</p><p>再进一步的 <code>-nn</code> 连端口号也不翻译成服务名——默认 <code>80</code> 会显示成 <code>http</code>。日常两杆枪：<code>-n</code> 图省事，<code>-nn</code> 要精确，生产排障用后者。</p><blockquote><p><strong>雪球 3 补</strong>：端口号被翻译成服务名这件事，雪球 9 回读 pcap 文件时当场应验——到时候少写一个 <code>n</code>，端口 <code>80</code> 就会显示成 <code>.http</code>。</p></blockquote><hr><h2 id="雪球-4-加上-bpf-过滤器-在内核里先把不要的包扔掉" tabindex="-1"><a class="header-anchor" href="#雪球-4-加上-bpf-过滤器-在内核里先把不要的包扔掉"><span>雪球 4：加上 BPF 过滤器，在内核里先把不要的包扔掉</span></a></h2><h3 id="_4-1-为什么必须过滤" tabindex="-1"><a class="header-anchor" href="#_4-1-为什么必须过滤"><span>4.1 为什么必须过滤</span></a></h3><p>不带过滤器抓生产网卡，等于用吸管喝洪水：屏幕刷屏、内核缓冲溢出丢包（<code>dropped by kernel</code> 飙升，雪球 2 的坑应验）、明文密码从眼前滚过。好在 tcpdump 的过滤<strong>不是</strong>抓回来再筛——过滤器会被编译成 <strong>BPF</strong>（Berkeley Packet Filter，伯克利包过滤器）指令，<strong>在内核里执行</strong>，不匹配的包根本不会复制给 tcpdump，代价极小。</p><p>🧗 眼见为实，<code>tcpdump -d</code> 能看到编译结果：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>$ tcpdump -d &quot;host 223.5.5.5&quot;</span></span>
<span class="line"><span>Warning: assuming Ethernet</span></span>
<span class="line"><span>(000) ldh      [12]</span></span>
<span class="line"><span>(001) jeq      #0x800           jt 2	jf 4</span></span>
<span class="line"><span>(002) ld       [26]</span></span>
<span class="line"><span>...</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>（读不懂没关系，知道「过滤器是编译成机器码在内核执行的」这个事实即可，主线用不上。）</p><h3 id="_4-2-实测与速查表" tabindex="-1"><a class="header-anchor" href="#_4-2-实测与速查表"><span>4.2 实测与速查表</span></a></h3><p>在 eth0 上只抓与公网 DNS <code>223.5.5.5</code> 有关的 ICMP——同一条 ping 流量，这次换到真实网卡上：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">tcpdump</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -ni</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> eth0</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> host</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 223.5.5.5</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -c</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 4</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> &amp;</span></span>
<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">ping</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -c</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 2</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 223.5.5.5</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>新加的东西只有过滤器 <code>host 223.5.5.5</code>：源<strong>或</strong>目的是这个地址的包都要。本机输出：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>14:03:05.689489 IP 172.22.212.111 &gt; 223.5.5.5: ICMP echo request, id 3, seq 1, length 64</span></span>
<span class="line"><span>14:03:05.695013 IP 223.5.5.5 &gt; 172.22.212.111: ICMP echo reply, id 3, seq 1, length 64</span></span>
<span class="line"><span>14:03:06.691236 IP 172.22.212.111 &gt; 223.5.5.5: ICMP echo request, id 3, seq 2, length 64</span></span>
<span class="line"><span>14:03:06.697121 IP 223.5.5.5 &gt; 172.22.212.111: ICMP echo reply, id 3, seq 2, length 64</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>四行全是和 <code>223.5.5.5</code> 的对话，一个杂包都没有——eth0 平时还跑着 SSH、DNS 等各种流量，全被内核里的过滤器挡在了门外。字段全是雪球 1 认过的老面孔，只是源地址换成了 <code>172.22.212.111</code>（本机 eth0 的门牌）。</p><p>常用表达式速查（以下写法均在本机 <code>-d</code> 编译验证通过）：</p><table><thead><tr><th>写法</th><th>匹配什么</th></tr></thead><tbody><tr><td><code>host 172.17.0.4</code></td><td>源<strong>或</strong>目的是这个地址</td></tr><tr><td><code>src host 172.17.0.4</code> / <code>dst host ...</code></td><td>只匹配一个方向</td></tr><tr><td><code>net 172.17.0.0/16</code></td><td>整个网段（第 2 篇的 CIDR 记法）</td></tr><tr><td><code>port 80</code> / <code>tcp port 80</code> / <code>udp port 53</code></td><td>端口，可限定协议</td></tr><tr><td><code>portrange 8000-8100</code></td><td>端口段</td></tr><tr><td><code>icmp</code> / <code>tcp</code> / <code>udp</code></td><td>按协议</td></tr><tr><td><code>and</code> / <code>or</code> / <code>not</code></td><td>组合以上所有条件</td></tr></tbody></table><p>组合起来就是日常主力句式，比如雪球 8 要用的「容器 172.17.0.4 的 80 端口流量」：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">tcpdump</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -ni</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> docker0</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &quot;host 172.17.0.4 and tcp port 80&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><blockquote><p><strong>雪球 4 补</strong>：表达式<strong>整体加引号</strong>——<code>and</code>、括号这类词和符号不转义会被 shell 抢先解释，报一堆看不懂的语法错。另一个习惯是<strong>先收窄再开抓</strong>：宁可抓少了再放宽，不要一开始就全量。</p></blockquote><hr><h2 id="雪球-5-加上-flags-字母表-读懂一次-curl-的完整一生" tabindex="-1"><a class="header-anchor" href="#雪球-5-加上-flags-字母表-读懂一次-curl-的完整一生"><span>雪球 5：加上 Flags 字母表，读懂一次 curl 的完整一生</span></a></h2><p>ICMP 看够了，本文后面的主角是 TCP——容器里跑的 Web 服务全是它。本机起一个临时 HTTP 服务，抓一次 <code>curl</code> 从握手到挥手的完整一生：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">python3</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -m</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> http.server</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 18099</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> --bind</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 127.0.0.1</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> &amp;</span></span>
<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">tcpdump</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -ni</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> lo</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &quot;tcp port 18099&quot;</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -c</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 12</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> &amp;</span></span>
<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">curl</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -s</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> http://127.0.0.1:18099/</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -o</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> /dev/null</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>三条命令第一次出现，拆开：</p><table><thead><tr><th>片段</th><th>含义</th></tr></thead><tbody><tr><td><code>python3 -m http.server 18099</code></td><td>起一个临时静态文件服务器，监听 18099</td></tr><tr><td><code>--bind 127.0.0.1</code></td><td>只绑回环——和开头案发那个服务同一个姿势</td></tr><tr><td><code>&quot;tcp port 18099&quot;</code></td><td>雪球 4 的句式：这个端口的 TCP 包</td></tr><tr><td><code>-c 12</code></td><td>预留 12 个包，握手 + 数据 + 挥手刚好装下</td></tr><tr><td><code>curl -s</code></td><td>静默模式，不打印进度条</td></tr><tr><td><code>-o /dev/null</code></td><td>响应体扔进黑洞——我们要看的是过程，不是页面</td></tr></tbody></table><p>本机输出（<code>options</code> 内容较长，已用 <code>...</code> 精简）：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>14:07:50.543715 IP 127.0.0.1.53622 &gt; 127.0.0.1.18099: Flags [S],     seq 2551389454, win 65495, options [mss 65495,...], length 0</span></span>
<span class="line"><span>14:07:50.543728 IP 127.0.0.1.18099 &gt; 127.0.0.1.53622: Flags [S.],   seq 2301513543, ack 2551389455, win 65483, options [...], length 0</span></span>
<span class="line"><span>14:07:50.543738 IP 127.0.0.1.53622 &gt; 127.0.0.1.18099: Flags [.],     ack 1, win 512, length 0</span></span>
<span class="line"><span>14:07:50.543812 IP 127.0.0.1.53622 &gt; 127.0.0.1.18099: Flags [P.],   seq 1:80, ack 1, win 512, length 79</span></span>
<span class="line"><span>14:07:50.543818 IP 127.0.0.1.18099 &gt; 127.0.0.1.53622: Flags [.],     ack 80, win 511, length 0</span></span>
<span class="line"><span>14:07:50.571386 IP 127.0.0.1.18099 &gt; 127.0.0.1.53622: Flags [P.],   seq 1:158, ack 80, win 512, length 157</span></span>
<span class="line"><span>...（省略 3 行纯确认与数据行）</span></span>
<span class="line"><span>14:07:50.571492 IP 127.0.0.1.18099 &gt; 127.0.0.1.53622: Flags [F.],   seq 1314, ack 80, win 512, length 0</span></span>
<span class="line"><span>14:07:50.571502 IP 127.0.0.1.53622 &gt; 127.0.0.1.18099: Flags [F.],   seq 80, ack 1314, win 567, length 0</span></span>
<span class="line"><span>14:07:50.571509 IP 127.0.0.1.18099 &gt; 127.0.0.1.53622: Flags [.],     ack 81, win 512, length 0</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>先认解剖结构——一行 TCP 输出的每个字段：</p><table><thead><tr><th>片段</th><th>含义</th></tr></thead><tbody><tr><td><code>127.0.0.1.53622 &gt; 127.0.0.1.18099</code></td><td><code>IP.端口</code>，源在左目的在右——地址和端口之间是<strong>点</strong>不是冒号；<code>53622</code> 是 curl 侧的临时端口</td></tr><tr><td><code>Flags [S.]</code></td><td>TCP 标志位，这个包在「说」的话，见下表</td></tr><tr><td><code>seq 1:80</code></td><td>本包携带的数据是字节流的第 1~79 字节</td></tr><tr><td><code>ack 80</code></td><td>我已收到对方的前 79 字节，期望下一个从 80 开始</td></tr><tr><td><code>win 512</code></td><td>接收窗口：我还能再收多少字节（排查慢连接时会用到）</td></tr><tr><td><code>length 79</code></td><td>携带的数据字节数，<code>length 0</code> = 纯控制包</td></tr><tr><td><code>options [mss 65495,...]</code></td><td>握手包附带的协商参数（最大段大小等），正文里常省略</td></tr></tbody></table><p>Flags 字母表（摘自手册，常用的六个）：</p><table><thead><tr><th>标记</th><th>名字</th><th>包在说什么</th></tr></thead><tbody><tr><td><code>[S]</code></td><td>SYN</td><td>「我想建立连接」</td></tr><tr><td><code>[S.]</code></td><td>SYN+ACK</td><td>「同意，我也确认」</td></tr><tr><td><code>[.]</code></td><td>ACK</td><td>「收到」（常见的无声确认）</td></tr><tr><td><code>[P.]</code></td><td>PSH+ACK</td><td>「这里有一段数据，请向上交付」</td></tr><tr><td><code>[F.]</code></td><td>FIN+ACK</td><td>「我说完了，想关连接」</td></tr><tr><td><code>[R.]</code></td><td>RST+ACK</td><td>「拒绝 / 出错了，连接作废」</td></tr></tbody></table><p>拿字母表逐行套上面的输出，故事就出来了：<strong>三次握手</strong> <code>[S]</code>→<code>[S.]</code>→<code>[.]</code>；<strong>发数据</strong> <code>[P.]</code>（79 字节正是 HTTP 请求）；<strong>收响应</strong> <code>[P.]</code>（157 字节是响应的前一段）；<strong>四次挥手</strong> <code>[F.]</code>→<code>[F.]</code>→<code>[.]</code>。再看开头那个连不上的案例——<code>[S]</code> 刚落地就换来 <code>[R.]</code>，就是内核在说「这个端口没人听」。排障最常见的判读就这几招：<strong>只见 <code>[S]</code> 不见 <code>[S.]</code> 是路断了；见 <code>[R.]</code> 是被拒；全是重传 <code>[P.]</code> 是丢包</strong>。</p><blockquote><p><strong>雪球 5 补</strong>：序号默认显示<strong>相对值</strong>（连接建立后按字节流偏移计），要看原始值加 <code>-S</code>。相对 seq 只在本机这份输出里自洽，别拿去跟别的机器抓的包对数。</p></blockquote><hr><h2 id="雪球-6-加上一本账对照——读透-ss-给开头的案子结案" tabindex="-1"><a class="header-anchor" href="#雪球-6-加上一本账对照——读透-ss-给开头的案子结案"><span>雪球 6：加上一本账对照——读透 ss，给开头的案子结案</span></a></h2><p>雪球 5 读懂了 <code>[R.]</code>，开头的案子在事件层其实已经破了。但配置层那本账也值得回头读透——<strong>两本证据合起来，才是完整现场</strong>。</p><p><code>ss</code>（<strong>s</strong>ocket <strong>s</strong>tatistics）列出内核里当前的 socket，是老牌 <code>netstat</code> 的现代继任者（数据来自 <code>/proc/net/tcp</code>）。三个选项各管一件事：</p><table><thead><tr><th>选项</th><th>含义</th><th>不加会怎样</th></tr></thead><tbody><tr><td><code>-t</code></td><td>只看 <strong>TCP</strong></td><td>UDP 等一起列出来</td></tr><tr><td><code>-l</code></td><td>只看 <strong>L</strong>istening（监听中的「服务端门」）</td><td>已建立的连接（ESTAB 等）也会列出</td></tr><tr><td><code>-n</code></td><td>地址、端口显示<strong>数字</strong>，不查名字</td><td><code>80</code> 显示成 <code>http</code>，还可能去查 DNS——和 tcpdump 的 <code>-n</code> 是同一个哲学：<strong>快、准、不污染现场</strong></td></tr></tbody></table><p><code>| grep 18097</code> 只是在几十行里聚焦你关心的端口。不带过滤看全貌（本机实测节选）：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">ss</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -tln</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>State  Recv-Q Send-Q Local Address:Port  Peer Address:PortProcess</span></span>
<span class="line"><span>LISTEN 0      4096         0.0.0.0:18080      0.0.0.0:*</span></span>
<span class="line"><span>LISTEN 0      4096   127.0.0.53%lo:53         0.0.0.0:*</span></span>
<span class="line"><span>LISTEN 0      511          0.0.0.0:80         0.0.0.0:*</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>五列的含义（LISTEN 行）：</p><table><thead><tr><th>列</th><th>含义</th></tr></thead><tbody><tr><td>State</td><td><code>LISTEN</code> = 一扇等着别人来敲的门</td></tr><tr><td>Recv-Q</td><td>已完成握手、排队等应用 accept 的连接数（持续增长 = 应用收不过来）</td></tr><tr><td>Send-Q</td><td>这个队列的上限（backlog）</td></tr><tr><td><strong>Local Address:Port</strong></td><td><strong>门开在哪个地址的哪个端口——排障时最要紧的一列</strong></td></tr><tr><td>Peer Address:Port</td><td>监听态下无意义，恒为 <code>0.0.0.0:*</code></td></tr></tbody></table><p>关键就在 Local Address 的两种写法（同一台机器、两个服务的对照，实测）：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>LISTEN 0      5          127.0.0.1:18097      ← 绑死环回：只有本机能敲开这扇门</span></span>
<span class="line"><span>LISTEN 0      5            0.0.0.0:18096      ← 绑 0.0.0.0：本机所有网卡的地址都能敲开</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>所以回头看：<code>ss</code> 从一开始就把答案写清了——「有个门，开在 <code>127.0.0.1</code>」。它没有骗人，只是容易被读成「LISTEN + 端口对上了 = 没问题」。<strong>配置层工具给的是局部真相</strong>（门开在哪），把局部真相拼成完整现场（敲门的包到底遭遇了什么），才是抓包工具的活。顺带一眼：全貌里那行 <code>0.0.0.0:18080</code>，正是雪球 8 容器 <code>-p 18080:80</code> 在宿主机开的门——到时候回来对号。</p><hr><h2 id="雪球-7-加上-a-和-s0-把包里的明文打出来" tabindex="-1"><a class="header-anchor" href="#雪球-7-加上-a-和-s0-把包里的明文打出来"><span>雪球 7：加上 <code>-A</code> 和 <code>-s0</code>，把包里的明文打出来</span></a></h2><p>TCP 行只告诉你「有多少数据」，<code>-A</code> 把数据内容按 ASCII 打出来：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">python3</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -m</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> http.server</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 18098</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> --bind</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 127.0.0.1</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> &amp;</span></span>
<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">tcpdump</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -A</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -s0</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -ni</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> lo</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &quot;tcp dst port 18098&quot;</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -c</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 4</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> &amp;</span></span>
<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">curl</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -s</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &quot;http://127.0.0.1:18098/hello?name=world&quot;</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -o</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> /dev/null</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>新加的两样：<code>-A</code> 按 ASCII 打印包的载荷；<code>-s0</code> 抓完整包（理由马上讲）。过滤器换成 <code>tcp dst port</code> 只留「去程」——要看的是 curl 发出的请求原文，响应的 HTML 会把屏幕刷爆。</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>14:16:53.114869 IP 127.0.0.1.42872 &gt; 127.0.0.1.18098: Flags [P.], seq 0:95, ack 1, win 512, length 95</span></span>
<span class="line"><span>E.....@.@.l..........xF.C..................</span></span>
<span class="line"><span>.X.K.X.KGET /hello?name=world HTTP/1.1</span></span>
<span class="line"><span>Host: 127.0.0.1:18098</span></span>
<span class="line"><span>User-Agent: curl/7.81.0</span></span>
<span class="line"><span>Accept: */*</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>逐行读：</p><table><thead><tr><th>行</th><th>一句话</th></tr></thead><tbody><tr><td><code>14:16:53.114869 IP ... length 95</code></td><td>雪球 5 的老 TCP 行：一个带 95 字节数据的 <code>[P.]</code> 包</td></tr><tr><td><code>E.....@.@.l...</code> 两行乱码</td><td>以太网/IP/TCP 头部的字节按 ASCII 显示，不可打印的都成了点——给机器看的，不用人读</td></tr><tr><td><code>GET /hello?name=world HTTP/1.1</code></td><td>HTTP 请求行：方法、路径（带查询串）、协议版本</td></tr><tr><td><code>Host: 127.0.0.1:18098</code></td><td>要访问的主机和端口</td></tr><tr><td><code>User-Agent: curl/7.81.0</code></td><td>客户端自报家门</td></tr><tr><td><code>Accept: */*</code></td><td>什么响应类型都收</td></tr></tbody></table><p>HTTP 请求的每一个字都看得见——包括没加密的口令、Cookie。<code>-s0</code> 的意思是「抓完整包」：snaplen 设为 0 即取默认 262144。老教程里人手一个 <code>-s 0</code>，是因为旧版默认只抓 68 字节会截断；4.99 时代不带也行，写了更稳（来龙去脉见文末「历史包袱」）。截断真的发生时，输出会标 <code>[|proto]</code>。顺带一句常识：<strong>HTTPS 的包抓出来是一串乱码，这是加密的本意</strong>——想看解密内容需要密钥配合 Wireshark，超出本文范围。</p><hr><h2 id="雪球-8-换一张口——docker0-上抓容器-eth0-上零包" tabindex="-1"><a class="header-anchor" href="#雪球-8-换一张口——docker0-上抓容器-eth0-上零包"><span>雪球 8：换一张口——docker0 上抓容器，eth0 上零包</span></a></h2><p>前面练的功夫，现在用到 Docker 上（这也是本系列作为 Docker 前置的正题）。本机有个发布过 <code>-p 18080:80</code> 的容器（第 4 篇 NAT 的主角，IP <code>172.17.0.4</code>），在 docker0 上看宿主机访问它的全程：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">tcpdump</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -ni</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> docker0</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &quot;host 172.17.0.4 and tcp port 80&quot;</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -c</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 8</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> &amp;</span></span>
<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">curl</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -s</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> http://172.17.0.4/</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -o</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> /dev/null</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -w</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &quot;HTTP %{http_code}\\n&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>新加的东西只有 <code>-i docker0</code>：镜头从 lo 换到 Docker 网桥。<code>curl</code> 的 <code>-w &quot;HTTP %{http_code}\\n&quot;</code> 表示请求结束后按格式串打印状态码变量。输出：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>HTTP 200</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>14:15:52.209291 IP 172.17.0.1.34164 &gt; 172.17.0.4.80: Flags [S],     seq 3551765619, win 64240, options [mss 1460,...], length 0</span></span>
<span class="line"><span>14:15:52.209322 IP 172.17.0.4.80 &gt; 172.17.0.1.34164: Flags [S.],   seq 2698906446, ack 3551765620, win 65160, options [...], length 0</span></span>
<span class="line"><span>14:15:52.209332 IP 172.17.0.1.34164 &gt; 172.17.0.4.80: Flags [.],     ack 1, win 502, length 0</span></span>
<span class="line"><span>14:15:52.209381 IP 172.17.0.1.34164 &gt; 172.17.0.4.80: Flags [P.],   seq 1:75, ack 1, win 502, length 74: HTTP: GET / HTTP/1.1</span></span>
<span class="line"><span>14:15:52.209564 IP 172.17.0.4.80 &gt; 172.17.0.1.34164: Flags [P.],   seq 1:239, ack 75, win 509, length 238: HTTP: HTTP/1.1 200 OK</span></span>
<span class="line"><span>...（省略 3 行）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>握手、<code>GET /</code>、<code>200 OK</code>，一网打尽——拿雪球 5 的字母表逐行套即可。三个新面孔：<code>172.17.0.1</code> 是 docker0（网关），<code>172.17.0.4</code> 是容器；行尾的 <code>HTTP: GET / HTTP/1.1</code>、<code>HTTP: HTTP/1.1 200 OK</code> 是 tcpdump 顺手认出的 HTTP 内容。</p><p><strong>同一时刻在 eth0 上抓会怎样？</strong>（过滤器换成容器地址，等 5 秒超时退出）：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">timeout</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 5</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> tcpdump</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -ni</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> eth0</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &quot;host 172.17.0.4&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>（curl 依旧 HTTP 200。）</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>0 packets captured</span></span>
<span class="line"><span>0 packets received by filter</span></span>
<span class="line"><span>0 packets dropped by kernel</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>一个包都没有。</strong> 宿主机与容器同在 <code>172.17.0.0/16</code> 这片网段（第 2 篇的 <code>scope link</code> 直连路由），流量只走 docker0，根本不经过 eth0——这就是「抓哪张口，就看见谁的流量」的反面教材：</p>`,125),i(d,{code:`eJxLy8kvT85ILCpR8AniUgACj2ilp+v2P9mx+9mcXTZJRfp2huZGeobmegZ6hkqxCrq6djVKKfnJ2alFBgpPdnQ97V//YnmjUo2CSzRMWCkWbI4LSK2CM8i0nU9nrkA1ysTKAqbONVoptSTDACz/fk/Hs67JT3b0Pu3Y8GL/zCe7Zj/taX2/pxNksZ5uhYIzFwD0fEKO`}),o[1]||=e(`<p>留给下一篇的钩子也在这：<strong>容器去 ping 公网时，eth0 上能抓到吗？源地址还是 <code>172.17.0.4</code> 吗？</strong>——第 4 篇用同样的手法拍 NAT 换头。</p><blockquote><p><strong>雪球 8 补 🧗（混杂模式的实测说明）</strong>：教材常说 tcpdump 默认把网卡设为混杂模式（看见「不发给本机」的包，<code>-p</code> 关闭）。但在本机（tcpdump 4.99.1）实测：抓包期间 <code>ip link show docker0</code> 并<strong>没有</strong>出现 PROMISC 标志；手动 <code>ip link set docker0 promisc on</code> 则立刻出现——说明是否置位由 libpcap 与系统决定，<code>-p</code> 的语义只是「不主动去开」。手册还明确：<code>any</code> 接口<strong>不会</strong>使用混杂模式。好在抓宿主↔容器、容器↔网关的流量并不需要它（去程是本机发出、回程目的 MAC 就是本机口）；现代交换网络里混杂模式的用武之地本也不多。</p></blockquote><hr><h2 id="雪球-9-加上-w-r-把现场存成可回放的证据" tabindex="-1"><a class="header-anchor" href="#雪球-9-加上-w-r-把现场存成可回放的证据"><span>雪球 9：加上 <code>-w</code>/<code>-r</code>，把现场存成可回放的证据</span></a></h2><p>屏幕会滚走，文件不会。<code>-w</code> 把<strong>原始包</strong>存成 pcap 文件（业界通用格式，Wireshark 直接打开）：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">tcpdump</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -ni</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> docker0</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &quot;host 172.17.0.4 and tcp port 80&quot;</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -c</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 6</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -w</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> /tmp/docker-http.pcap</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> &amp;</span></span>
<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">curl</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -s</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> http://172.17.0.4/</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -o</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> /dev/null</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>新加的只有 <code>-w /tmp/docker-http.pcap</code>：不解析上屏，原样写文件。本机只打印了结尾统计：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>6 packets captured</span></span>
<span class="line"><span>12 packets received by filter</span></span>
<span class="line"><span>0 packets dropped by kernel</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>（12 对 6 又是熟悉的倍数——雪球 2 讲过 <code>received by filter</code> 的计数语义，不是丢包。）</p><p>看一眼产物：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">ls</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -l</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> /tmp/docker-http.pcap</span></span>
<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">file</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> /tmp/docker-http.pcap</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>-rw-r--r-- 1 tcpdump tcpdump 844 Aug 17 14:16 /tmp/docker-http.pcap</span></span>
<span class="line"><span>/tmp/docker-http.pcap: pcap capture file, microsecond ts (little-endian) - version 2.4 (Ethernet, capture length 262144)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>逐行拆：<code>ls -l</code> 那行里 <code>-rw-r--r--</code> 是权限（别人只读不可写），属主显示 <strong>tcpdump</strong> 而不是 root——tcpdump 写文件时默认<strong>降权</strong>到 tcpdump 用户（<code>-Z</code> 选项的默认值，安全设计），<code>844</code> 是文件字节数。<code>file</code> 那行交代格式：pcap 捕获文件、微秒精度时间戳、小端序、版本 2.4、以太网链路、抓取长度 262144。</p><p>回读用 <code>-r</code>（不需要特权）：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">tcpdump</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -nn</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -r</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> /tmp/docker-http.pcap</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> | </span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">head</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -4</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>reading from file /tmp/docker-http.pcap, link-type EN10MB (Ethernet), snapshot length 262144</span></span>
<span class="line"><span>14:16:00.349015 IP 172.17.0.1.36820 &gt; 172.17.0.4.80: Flags [S], ...</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p><code>reading from file ...</code> 的 banner 说明这回不是听网卡、是读文件；<code>head -4</code> 只取前几行。注意 <code>36820 &gt; 80</code> 的端口——<strong>雪球 3 埋的坑在这应验</strong>：若省掉一个 <code>n</code>（只 <code>-n</code> 不 <code>-nn</code>），同样的文件会显示成 <code>172.17.0.4.http</code>，端口被翻译成了服务名。文件是原始证据，回读时才决定怎么呈现，这也是「落盘再分析」的好处之一。</p><p>生产上长时间抓包的配套件：<code>-C</code> 按大小切文件、<code>-W</code> 限制个数（环形覆盖）、<code>-G</code> 按时间轮转——名字先记下，用到再查手册。</p><p><strong>收尾清理</strong>：本文起过三个练手服务（开头 18097、雪球 5 的 18099、雪球 7 的 18098，都是 <code>python3 -m http.server</code>），连同落盘的 pcap 一起清掉（<code>pkill -f</code> 按命令行匹配杀进程，<code>rm -f</code> 删文件）：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">pkill</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -f</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> http.server</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> &amp;&amp; </span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">rm</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -f</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> /tmp/docker-http.pcap</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><hr><h2 id="参数怎么记-对照哪一球用过" tabindex="-1"><a class="header-anchor" href="#参数怎么记-对照哪一球用过"><span>参数怎么记（对照哪一球用过）</span></a></h2><p>每个选项都是在某一球里带着效果出场过的，按出场顺序记：</p><table><thead><tr><th>选项/命令</th><th>干什么</th><th>在哪一球用过</th></tr></thead><tbody><tr><td><code>-D</code></td><td>列出可抓的口</td><td>1</td></tr><tr><td><code>-i &lt;口&gt;</code> / <code>any</code></td><td>选口 / 全口并带 <code>In</code>、<code>Out</code> 方向</td><td>1 / 2</td></tr><tr><td><code>-n</code> / <code>-nn</code></td><td>不查名字 / 连端口也不翻译</td><td>1、3</td></tr><tr><td><code>-c N</code></td><td>抓满 N 个包退出</td><td>1</td></tr><tr><td><code>host</code>/<code>net</code>/<code>port</code> + <code>and</code>/<code>or</code>/<code>not</code></td><td>BPF 过滤表达式（整体加引号）</td><td>4、8</td></tr><tr><td><code>-d</code> 🧗</td><td>看过滤器的编译结果</td><td>4</td></tr><tr><td><code>-S</code></td><td>序号显示原始值</td><td>5 补</td></tr><tr><td><code>-A</code> / <code>-s0</code></td><td>打印明文 / 抓完整包</td><td>7</td></tr><tr><td><code>-w</code> / <code>-r</code></td><td>落盘 / 回读</td><td>9</td></tr><tr><td><code>-C</code>/<code>-W</code>/<code>-G</code></td><td>按大小切文件 / 限个数 / 按时间轮转</td><td>9（记名字即可）</td></tr><tr><td><code>ss -tln</code></td><td>账本：门开在哪</td><td>开头、6</td></tr><tr><td><code>python3 -m http.server</code></td><td>练手服务</td><td>开头、5、7</td></tr><tr><td><code>file</code> / <code>pkill -f</code></td><td>认文件格式 / 按命令行杀进程</td><td>9</td></tr></tbody></table><h2 id="历史包袱-老教程里的三处版本痕迹" tabindex="-1"><a class="header-anchor" href="#历史包袱-老教程里的三处版本痕迹"><span>历史包袱：老教程里的三处版本痕迹</span></a></h2><ul><li><strong>人手一个 <code>-s 0</code></strong>：旧版 tcpdump 默认 snaplen 只有 68 字节，HTTP 包必截断，所以老教程见包就写 <code>-s 0</code>。4.99 起默认 262144（雪球 1 的 banner 就是本机证据），不带也基本够——写了更稳，不算错。</li><li><strong><code>netstat -tln</code></strong>：<code>ss</code> 出现前的老写法，两者都读 <code>/proc/net/tcp</code>；新系统请用 <code>ss</code>。</li><li><strong>版本差</strong>：本机是 Ubuntu 22.04 仓库的 tcpdump 4.99.1 + libpcap 1.10.1；上游最新稳定版 4.99.6（2025-12-30 发布），线上手册已是对应 5.0.0-PRE-GIT 的版本。<code>received by filter</code> 语义依操作系统而定等表述以手册为准，本文写法各版通用。</li></ul><h2 id="和系列其它篇" tabindex="-1"><a class="header-anchor" href="#和系列其它篇"><span>和系列其它篇</span></a></h2><table><thead><tr><th>相关篇</th><th>在这一路上出现的位置</th></tr></thead><tbody><tr><td><a href="/Linux/basics/linux-02-ip-subnet-gateway">第 2 篇《读 Docker 网络前要懂的 IP、网段与网关》</a></td><td><code>scope host</code>（开头案子的根因）、<code>scope link</code> 直连路由（雪球 8）、<code>eth0@if88</code>/veth 伏笔（雪球 1）</td></tr><tr><td><a href="/Linux/basics/linux-04-nat">第 4 篇《NAT 白话拆解》</a></td><td>下一篇：两侧抓包拍 NAT 换头，主角就是雪球 8 的 <code>172.17.0.4</code> 容器</td></tr><tr><td><a href="/%E4%BA%91%E5%8E%9F%E7%94%9F/docker/docker-11-network">Docker 第 11 篇《Docker 网络——从 localhost 不通滚到能用名字互访》</a></td><td>veth 这根线怎么接、网桥怎么转——雪球 8 docker0 的下一层</td></tr></tbody></table><h2 id="小结" tabindex="-1"><a class="header-anchor" href="#小结"><span>小结</span></a></h2><p>同一条流量滚了九球：</p><ol><li><strong>三件套起步</strong>：<code>-D</code> 认口、<code>-i</code> 选口、<code>-n</code> 不查名、<code>-c</code> 限个数；banner 里的 snaplen 262144 先记下。</li><li><strong>结尾统计</strong>：<code>dropped by kernel</code> 非 0 = 现场已失真，这份抓包不能当证据；<code>received</code> 数字翻倍是 lo 双计不是丢包；<code>any</code> 带方向，先定位再细抓。</li><li><strong><code>-nn</code></strong>：地址、端口都不翻译——生产排障的默认姿势。</li><li><strong>BPF 过滤器</strong>：编译进内核执行，先收窄再开抓，表达式整体加引号。</li><li><strong>Flags 字母表</strong>：<code>[S]</code> 请求连接、<code>[S.]</code> 同意、<code>[R.]</code> 拒绝（开头案例的真凶）、<code>[P.]</code> 带数据、<code>[F.]</code> 关闭；只见 <code>[S]</code> 不见 <code>[S.]</code> 是路断了。</li><li><strong>合读账本</strong>：<code>ss -tln</code> 的 Local Address:Port 写明门开在哪（绑 <code>127.0.0.1</code> 只有本机能敲、绑 <code>0.0.0.0</code> 所有地址可敲）——配置层给局部真相，抓包补完整现场。</li><li><strong><code>-A</code> + <code>-s0</code></strong>：明文一屏可见（口令也在内）；HTTPS 乱码是加密的本意。</li><li><strong>docker0 抓容器</strong>：宿主↔容器在 eth0 上零流量（同网段 <code>scope link</code> 直连）；混杂模式是否置位依系统而定，实测 4.99.1 未置位也不影响本文场景。</li><li><strong><code>-w</code>/<code>-r</code></strong>：pcap 是可回放的原始证据，回读不要特权，Wireshark 可接着分析。</li></ol><p><strong>思考题</strong>：</p><blockquote><ol><li>雪球 8 证明「宿主→容器」的流量在 eth0 上抓不到。那<strong>容器 ping 223.5.5.5</strong> 时，<code>tcpdump -ni eth0 &quot;host 223.5.5.5&quot;</code> 能抓到包吗？如果能，源地址会写谁的名字？（提示：回看第 2 篇「出网段先交给网关」；答案就是下一篇的正文。）</li><li>生产机上同事执行了 <code>tcpdump -ni eth0</code>（无过滤器、无 <code>-c</code>）十分钟后 Ctrl+C，统计显示 <code>dropped by kernel = 15000</code>。这份抓包能作为排障依据吗？你会给他哪三条改进命令？（提示：雪球 2 的补、雪球 4 的两个习惯、雪球 9 的落盘。）</li></ol></blockquote><p>下一篇：<a href="/Linux/basics/linux-04-nat">《NAT 白话拆解》</a>。</p><hr><h2 id="参考资料" tabindex="-1"><a class="header-anchor" href="#参考资料"><span>参考资料</span></a></h2><ul><li><a href="https://www.tcpdump.org/manpages/tcpdump.1.html" target="_blank" rel="noopener noreferrer">tcpdump(1) 官方手册</a>（线上版对应 5.0.0-PRE-GIT，更新于 2026-07；统计三行、Flags 字母表、<code>any</code> 与混杂模式的表述均出自此处）</li><li><a href="https://www.tcpdump.org/" target="_blank" rel="noopener noreferrer">tcpdump.org</a> — 当前稳定版 4.99.6（2025-12-30）；过滤器语法详见配套的 <a href="https://www.tcpdump.org/manpages/pcap-filter.7.html" target="_blank" rel="noopener noreferrer">pcap-filter(7)</a></li><li><a href="https://www.wireshark.org/" target="_blank" rel="noopener noreferrer">Wireshark</a> — pcap 文件的图形化分析器</li><li>本机实测环境：WSL2 Ubuntu-22.04，tcpdump 4.99.1 + libpcap 1.10.1，Docker Engine 29.1.3</li></ul>`,37)])}var l=a(s,[[`render`,c]]);export{o as _pageData,l as default};